function exec(){

  var bIsMidToUid = quickerGetVar('bIsMidToUid');
  // var inUrl = quickerGetVar('inputURL');  // 读取text变量值, (text 是动作里的变量)

  if (bIsMidToUid) {
    var mid = quickerGetVar('mid');
  	var uid = mid2url(mid);
  	quickerSetVar('uid', uid );
  	
  }
  
  else {
    var uid = String(quickerGetVar('uid'));
    var mid = url2mid(uid);
    quickerSetVar('mid', mid ); //输出修改后的值到text变量中。
  }
  
  return 0; //返回0表示成功。返回其他数字表示失败。
  
}
