public Tuple<int, int, int> CountChineseAndEnglish(string str)  
{  
    // 匹配中文字符的正则表达式，包括各种全角符号  
    Regex regexChinese = new Regex(@"[\u4e00-\u9fa5\uFF00-\uFFEF]");  
    
    // 匹配英文字符和数字的正则表达式  
    Regex regexEnglishAndNumber = new Regex(@"[a-zA-Z0-9]");  
    
    int chineseCount = regexChinese.Matches(str).Count;  
    int englishAndNumberCount = regexEnglishAndNumber.Matches(str).Count;  
    int sumCount = chineseCount + englishAndNumberCount;
    
    return Tuple.Create(chineseCount, englishAndNumberCount, sumCount);  
}

// 示例测试  
var text = "abcd 中文";
var result = CountChineseAndEnglish("我不喜欢12346");  

Console.WriteLine(result.Item1); // 中文数量，输出4  
Console.WriteLine(result.Item2); // 英文或数字数量，输出13

return "中文字符："+result.Item1+"  英文字符："+result.Item2+"；合计：" + result.Item3;

