using System.Windows.Forms;
using System.Text;

// Quicker将会调用的函数
public static void Exec(Quicker.Public.IStepContext context)
{

	var Value = context.GetVarValue("output");
	
	string html = "<div>"+Value+"</div>";
	
	var sb = new StringBuilder();
	 
	const string header = @"Format:HTML Format
	Version:1.0
	StartHTML:<<<<<<<1
	EndHTML:<<<<<<<2
	StartFragment:<<<<<<<3
	EndFragment:<<<<<<<4
	StartSelection:<<<<<<<3
	EndSelection:<<<<<<<4
	";
 
    sb.Append(header);
    int startHtml = sb.Length;

    sb.Append(@"<!DOCTYPE HTML PUBLIC ""-//W3C//DTD HTML 4.0 Transitional//EN"">");
    sb.Append(@"<!--StartFragment-->");
    int fragmentStart = sb.Length;

    sb.Append(html);
    int fragmentEnd = sb.Length;

    sb.Append(@"<!--EndFragment-->");
    int endHtml = sb.Length;

    // Backpatch offsets

    sb.Replace("<<<<<<<1", String.Format("{0,8}", startHtml));
    sb.Replace("<<<<<<<2", String.Format("{0,8}", endHtml));
    sb.Replace("<<<<<<<3", String.Format("{0,8}", fragmentStart));
    sb.Replace("<<<<<<<4", String.Format("{0,8}", fragmentEnd));
            
	Clipboard.SetData(DataFormats.Html, sb.ToString());
}
